class Game:
    def __init__(self):
        self.map = mazelibrary.GameMap()\        self.player = mazelibrary.Player(1, 1)\        self.enemies = [mazelibrary.Enemy(random.randint(0, self.map.width - 1), random.randint(0, self.map.height - 1)) for _ in range(5)]

    def run(self):
        while True:
            print(self.map.map)
            move = input('Enter a direction (w, a, s, d): ').lower()
            if move == 'w' and self.player.y > 0:
                self.player.y -= 1
            elif move =='s' and self.player.y < self.map.height - 1:
                self.player.y += 1
            elif move == 'a' and self.player.x > 0:
                self.player.x -= 1
            elif move == 'd' and self.player.x < self.map.width - 1:
                self.player.x += 1

